int Partition(int low, int high)
{
    int pivot = a[low];
    while (low < high) {
        while (low < high && a[high] >= pivot)
            high--;
        a[low] = a[high];
        while (low < high && a[low] <= pivot)
            low++;
        a[high] = a[low];
    }
    a[low] = pivot;
    return low;
}

void QuickSort(int low, int high)
{
    int p, i;
    if (low >= high)
        return;
    p = Partition(low, high);
    for (i = 0; i < n; i++)
