#include <stdio.h>
/* 在 a[0..n-1] 中把以 i 为根的子树调成大根堆 */
void Sift(int a[], int i, int n)
{
    int x = a[i], j = 2 * i + 1;
    while (j < n) {
        if (j + 1 < n && a[j] < a[j + 1])
            j++;
        if (x >= a[j])
            break;
        a[i] = a[j];
        i = j;
        j = 2 * i + 1;
    }
    a[i] = x;
}
void Print(int a[], int n)
{
